import {compile,step,encode,template,validateDraft} from './engine.mjs';
import {t,esc} from './ui.mjs';
let nodes=template(),state=[],tick=0,source=null,history=[];try{const saved=localStorage.getItem('cirra-draft-v1');if(saved)nodes=validateDraft(JSON.parse(saved));}catch{}
const save=()=>localStorage.setItem('cirra-draft-v1',JSON.stringify({version:1,nodes}));
function backup(){history.push(JSON.stringify(nodes));if(history.length>50)history.shift();}
function download(value,name){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
export function mountStudio(app,onFill){let project=localStorage.getItem("fillout-studio-project")||"";const $=s=>app.querySelector(s);app.innerHTML=`<div class="studio-head"><div><div class="eyebrow">FillOut / OpenBook · ${t("STUDIO","工作室")}</div><h1>${t('Circuit workspace','电路工作区')}</h1></div><div class="actions"><button id="undo">${t('Undo','撤销')}</button><button id="export">${t('Export draft','导出草稿')}</button><button id="import">${t('Import draft','导入草稿')}</button></div></div><div class="studio-grid"><aside class="toolbox"><div class="eyebrow">${t('Design','设计')}</div>${[['input','Input pin','输入端口'],['nand','Quote','Quote'],['mem','Settle','Settle'],['output','Output pin','输出端口']].map(([type,en,zh])=>`<button data-add="${type}">${t(en,zh)} <span>+</span></button>`).join('')}<p class="hint">${t('Connect an output port to an input port. Drag node headers to move them. Click an input bit to toggle it.','连接输出与输入端口。拖动节点标题可移动节点。点击输入位可切换数值。')}</p><label>${t('Examples','示例')}<select id="example"><option value="">${t('Choose an example','选择示例')}</option value="nand">Quote</option><option value="not">${t("NOT","非门")}</option><option value="memory">Settle</option></select></label><p class="hint">${t('Draft saved in this browser.','草稿保存在当前浏览器。')}</p></aside><div class="canvas-wrap"><div class="canvas" id="canvas"></div></div><aside class="inspector"><h2>${t("Create circuit","创建电路")}</h2><label class="project-choice">${t("Project","项目")}<select id="studio-project"><option value="">${t("Choose project","选择项目")}</option><option value="openbook">OpenBook</option><option value="fillout">FillOut</option></select></label><p id="project-summary" class="hint"></p><p id="validation"></p><div id="metrics"></div><button id="netlist" class="primary">${t('Export netlist','导出网表')}</button><p class="muted">${t('Creating a circuit NFT permanently locks the Quote and Settle counts shown above. Parts cannot be recovered. Exporting is free.','创建电路 NFT 将永久锁定上述数量的 Quote 和 Settle，无法取回。导出免费。')}</p><button id="create-circuit" class="primary">${t('Create circuit NFT','创建电路 NFT')}</button></aside></div><div class="outputs"><div><h3>${t('Simulation','模拟')}</h3><span id="tick"></span><p class="hint">${t("Step updates every Settle memory once. Reset sets inputs and memory to 0; your circuit stays on the canvas.","运行一步会更新一次所有 Settle 的存储状态。重置会将输入和存储状态归零，画布上的电路保持不变。")}</p></div><div id="outputs"></div><div class="actions"><button id="reset">${t('Reset simulation','重置模拟')}</button><button id="step" class="primary">${t('Step +1','运行一步')}</button></div></div><input type="file" id="file" accept=".json,application/json" hidden><p id="studio-error" role="status"></p>`;
const fail=()=>{$('#studio-error').textContent=t('Unable to import this draft. Use a valid FillOut draft with up to 512 nodes.','无法导入草稿。请使用最多 512 个节点的有效 FillOut 草稿。');};
function draw(){ $("#project-summary").textContent=project?(project==="openbook"?"OpenBook":"FillOut")+t(" Quote / Settle will be used for this circuit."," 的 Quote / Settle 将用于此电路。"):t("Select the project whose parts you want to use.","请选择要使用哪个项目的组件。");const canvas=$('#canvas');let ir,result;try{ir=compile(nodes);result=step(ir,state.length===ir.localStateCount?state:Array(ir.localStateCount).fill(0),ir.inputs.map(n=>n.value));$('#validation').textContent=t('✓ Circuit valid','✓ 电路有效');$('#metrics').innerHTML=[['Input pins','输入端口',ir.nInputs],['Output pins','输出端口',ir.outputs.length],['Quote','Quote',ir.ops.length],['Settle','Settle',ir.localStateCount],['Netlist bytes','网表字节数',(encode(ir).length-2)/2]].map(([en,zh,n])=>`<p>${t(en,zh)} <strong>${n}</strong></p>`).join('');}catch{$('#validation').textContent=t('Connect all inputs. Feedback needs Settle memory.','请连接所有输入。反馈需要 Settle 存储器。');$('#metrics').textContent='—';}$('#netlist').disabled=!ir;$('#create-circuit').disabled=!ir||!(ir.ops.length+ir.localStateCount)||!onFill||!project;$('#create-circuit').onclick=()=>{if(ir&&onFill)onFill(encode(ir),ir.ops.length,ir.localStateCount,project);};$('#step').disabled=!result;$('#tick').textContent=t('Step ','步骤 ')+tick;$('#outputs').innerHTML=result?result.outputs.map((v,i)=>`<span>${t("OUT","输出")} ${i} <b class="output-bit">${v}</b></span>`).join(' '):'—';
const value=n=>result&&ir.signals.has(n.id)?result.signals[ir.signals.get(n.id)]:null;
canvas.style.width=Math.max(760,...nodes.map(n=>n.x+180))+'px';canvas.style.height=Math.max(560,...nodes.map(n=>n.y+140))+'px';canvas.innerHTML=`<svg class="wires">${nodes.flatMap(n=>n.ins.map((s,i)=>{const p=nodes.find(x=>x.id===s);if(!p)return '';return `<path class="wire ${value(p)===1?'high':''}" d="M${p.x+128},${p.y+53} C${p.x+190},${p.y+53} ${n.x-60},${n.y+50+i*24} ${n.x},${n.y+50+i*24}"/>`;})).join('')}</svg>`+nodes.map(n=>`<div class="node ${n.type}" style="left:${n.x}px;top:${n.y}px"><div class="node-title" data-drag="${n.id}">${({input:t('IN','输入'),output:t('OUT','输出'),nand:'Quote',mem:'Settle'})[n.type]}<button data-delete="${n.id}" aria-label="${t('Delete node','删除节点')}">×</button></div><div class="node-body">${n.type==='input'?`<button data-bit="${n.id}">${n.value}</button>`:n.type==='output'?(result?result.outputs[ir.outputs.findIndex(x=>x.id===n.id)]:'—'):n.type==='nand'?t('NAND · 2 → 1','与非门 · 2 → 1'):t('Memory: ','存储：')+(value(n)??0)}</div>${n.ins.map((s,i)=>`<button class="port in" style="top:${50+i*24}px" data-target="${n.id}" data-pin="${i}" aria-label="${t('Input port','输入端口')} ${i}"></button>`).join('')}${n.type!=='output'?`<button class="port out ${source===n.id?'chosen':''}" data-source="${n.id}" aria-label="${t('Output port','输出端口')}"></button>`:''}</div>`).join('');
canvas.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{source=b.dataset.source;draw();});canvas.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{if(!source)return;backup();nodes.find(n=>n.id===b.dataset.target).ins[Number(b.dataset.pin)]=source;source=null;state=[];save();draw();});canvas.querySelectorAll('[data-bit]').forEach(b=>b.onclick=()=>{backup();nodes.find(n=>n.id===b.dataset.bit).value^=1;save();draw();});canvas.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{backup();nodes=nodes.filter(n=>n.id!==b.dataset.delete);nodes.forEach(n=>n.ins=n.ins.map(i=>i===b.dataset.delete?null:i));state=[];save();draw();});canvas.querySelectorAll('[data-drag]').forEach(el=>el.onpointerdown=e=>{if(e.target.closest('button'))return;const n=nodes.find(n=>n.id===el.dataset.drag),x=n.x,y=n.y,cx=e.clientX,cy=e.clientY;backup();el.setPointerCapture(e.pointerId);el.onpointermove=v=>{n.x=Math.max(10,Math.min(1900,x+v.clientX-cx));n.y=Math.max(10,Math.min(1900,y+v.clientY-cy));el.parentElement.style.left=n.x+'px';el.parentElement.style.top=n.y+'px';};el.onpointerup=()=>{el.onpointermove=null;save();draw();};});$('#step').onclick=()=>{if(!result)return;state=result.nextState;tick++;draw();};$('#netlist').onclick=()=>download({format:'acdv/1',binaryHex:encode(ir)},'fillout-netlist.json');}
app.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(nodes.length>=512)return;backup();const type=b.dataset.add;nodes.push({id:'n'+(Math.max(0,...nodes.map(n=>Number(n.id.slice(1))))+1),type,x:80+(nodes.length%5)*130,y:60+(nodes.length%4)*100,ins:Array(type==='nand'?2:type==='input'?0:1).fill(null),...(type==='input'?{value:0}:{})});state=[];save();draw();});$('#undo').onclick=()=>{if(history.length){nodes=JSON.parse(history.pop());state=[];save();draw();}};$('#example').onchange=e=>{if(e.target.value){backup();nodes=template(e.target.value);state=[];tick=0;save();draw();}};$('#export').onclick=()=>download({version:1,nodes},'fillout-draft.json');$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const f=e.target.files[0];if(!f||f.size>500000)throw Error();const n=validateDraft(JSON.parse(await f.text()));backup();nodes=n;state=[];tick=0;save();draw();}catch{fail();}};$('#reset').onclick=()=>{backup();nodes.forEach(n=>{if(n.type==='input')n.value=0;});state=[];tick=0;source=null;save();draw();$('#studio-error').textContent=t("Simulation reset: inputs and memory are 0.","模拟已重置：输入和存储状态均为 0。");};$('#studio-project').value=project;$('#studio-project').onchange=e=>{project=e.target.value;localStorage.setItem('fillout-studio-project',project);draw();};draw();}
